            let isRange = false;
            for (let i = 0; i < cellRefs.length - 1; i++) {
                const currentRef = cellRefs[i];
                const nextRef = cellRefs[i + 1];

                // Comprobamos si el siguiente elemento es un rango o una celda adyacente en la misma columna/fila
                if (currentRef.match(/[A-Z]+/) && nextRef.match(/[A-Z]/) && currentRef !== nextRef) {
                    const col1 = currentRef[0];
                    const row1 = parseInt(currentRef.substring(1));
                    const col2 = nextRef[0];
                    const row2 = parseInt(nextRef.substring(1));

                    // Simple chequeo de rango (misma columna, filas consecutivas)
                    if (col1 === col2 && Math.abs(row1 - row2) > 1) {
                        isRange = true;
                        break;
                    }
                }
