                let startCol = startRef[0];
                let startRow = parseInt(startRef.substring(1));
                let endCol = endRef[0];
                let endRow = parseInt(endRef.substring(1));

                // Iterar sobre el rango y sumar los valores
                for (let r = startRow; r <= endRow; r++) {
                    for (let c = startCol; c <= endCol; c++) {
                        const ref = `${String.fromCharCode(startCol.charCodeAt(0) + (c - startCol.charCodeAt(0)))}${r}`;
                        sum += getCellValue(ref);
                    }
                }
                return sum;

            } else {
                // Si es una lista de celdas sueltas (A1;B2;C3) o solo referencias separadas por comas/espacios.
                const individualRefs = content.split(/[,;\s]+/).filter(r => r);
                for (const ref of individualRefs) {
                    sum += getCellValue(ref);
                }
                return sum;
            }
        });
    }

    // 2. Manejo de operaciones aritméticas básicas (A1-B1, A1*B1, etc.)
    // Reemplazar todas las referencias de celda con sus valores numéricos para que eval() funcione.
