 * Se adjunta un listener al contenedor principal para capturar eventos 
 * en cualquier celda editable (td con data-cell).
 */
function setupCellEditing() {
    const spreadsheet = document.getElementById('spreadsheet');

    if (!spreadsheet) {
        console.error("Error: No se encontró la tabla de cálculo.");
        return;
    }

    // Helper function to recalculate all dependent cells when a specific cell changes
    const recalculateDependencies = (changedElement) => {
        const changedRef = changedElement.getAttribute('data-cell');
        if (!changedRef) return;

        // Iterate over all formula cells in the spreadsheet
        document.querySelectorAll('#spreadsheet td[data-cell]').forEach(td => {
            const formula = td.innerText.trim();

            // Check if it's a formula and if it references the changed cell
            if (formula && formula.startsWith('=') && formula.includes(changedRef)) {
                calculateFormula(td);
            }
        });
    };

    // Usamos event delegation para escuchar en toda la tabla, 
    // pero solo actuar si el elemento objetivo es una celda de datos editable.
    spreadsheet.addEventListener('input', function(event) {
        const target = event.target;

        if (target.tagName === 'TD' && target.hasAttribute('data-cell')) {
            // 1. Trigger calculation for the target cell itself
            calculateFormula(target);

            // 2. Propagate calculation to dependent cells
            recalculateDependencies(target);
        }
    });

    // También es bueno manejar el blur (cuando sale de la celda) para simular un "guardado" o validación final.
