    spreadsheet.addEventListener('click', function(e) {
        const target = e.target;
        if (target.tagName === 'TD' && !target.hasAttribute('data-cell')) return;

        // Deselect previous active cell
        if (activeCell) {
            activeCell.classList.remove('selected');
        }

        // Select new active cell
        activeCell = target;
        activeCell.classList.add('selected');
    });

    // Handle contenteditable changes (input/blur)
    spreadsheet.addEventListener('input', function(e) {
        if (e.target.tagName === 'TD') {
            handleCellInput(e.target);
        }
    });

    // Handle focus change to ensure active cell is set even if clicking outside
    document.body.addEventListener('focusin', function(e) {
        if (e.target.closest('#spreadsheet')) {
            const target = e.target.closest('td');
            if (target && !activeCell || activeCell !== target) {
                // If focus moves to a cell, update activeCell and re-apply selection class
                if (activeCell) {
                    activeCell.classList.remove('selected');
                }
                activeCell = target;
                activeCell.classList.add('selected');
            }
        }
    });

    // Setup color tool listener
    backgroundColorInput.addEventListener('input', handleColorChange);
}

/**
 * Handles the change event from the background color picker.
 * Applies the selected color to the currently active cell.
 */
function handleColorChange(e) {
    const color = e.target.value;
    if (activeCell) {
        // FIX: Ensure the style is applied directly and overrides previous styles.
        activeCell.style.backgroundColor = color;
    } else {
        console.warn("No active cell selected to apply background color.");
    }
}

/**
 * Handles input changes in a specific editable cell (e.g., formula entry).
 * @param {HTMLElement} cell - The <td> element that was edited.
 */
function handleCellInput(cell) {
    // Basic validation/cleanup can go here if needed, but for now, just ensure the active cell is updated.
    if (activeCell !== cell) {
        // If input happens on a cell that isn't marked as active by click, mark it and update selection.
        if (activeCell) activeCell.classList.remove('selected');
        activeCell = cell;
        activeCell.classList.add('selected');
    }
    // Trigger recalculation if necessary after input
    calculateFormula(cell);
}

