    const [colChar, rowNum] = cellRef.toUpperCase().match(/([A-Z]+)([0-9]+)/);

    if (!colChar || !rowNum) return '';

    // Calculate column index (A=1, B=2, ...) and row index (1-based)
    const colIndex = colChar.charCodeAt(0) - 'A'.charCodeAt(0);
    const rowIndex = parseInt(rowNum) - 1;

    // Find the correct row and cell within the table body
