    if (rowIndex < 0 || rowIndex >= rows.length) return '';

    const targetRow = rows[rowIndex];
    const cells = targetRow.querySelectorAll('td');
    if (colIndex < 0 || colIndex >= cells.length) return '';

    const cellElement = cells[colIndex];
    let value = cellElement.innerText.trim();

    // Attempt to convert formula strings to actual values if they look like formulas
    if (value.startsWith('=')) {
