function handleColumnSelection(event) {
    const target = event.currentTarget;
    if (!target || !target.dataset.colIndex) return;

    const colIndex = parseInt(target.dataset.colIndex);
    const columnName = target.textContent.trim();
    const spreadsheetBody = document.querySelector('#spreadsheet tbody');
    const colorTool = document.getElementById('background-color');
    const selectedColor = colorTool ? colorTool.value : '#ffffff';

    // 1. Borrar contenido de la columna
    let contentCleared = false;
    document.querySelectorAll('#spreadsheet td').forEach((cell, rowIndex) => {
        // Los datos comienzan en el índice 0 del tbody (que corresponde a A2 si contamos desde 1).
        // El índice de la columna es relativo al inicio de los TDs (después del th de la fila label).
        if (cell.dataset.colIndex == colIndex) {
            const originalContent = cell.textContent;
            if (originalContent !== '') {
                cell.textContent = '';
                contentCleared = true;
            }
        }
    });

    // 2. Cambiar el color de fondo de todas sus celdas
    let backgroundColored = false;
    document.querySelectorAll('#spreadsheet td').forEach((cell, rowIndex) => {
        if (cell.dataset.colIndex == colIndex) {
            cell.style.backgroundColor = selectedColor;
            backgroundColored = true;
        }
    });

    // 3. Borrar la columna (DOM manipulation)
    const columnCells = [];
    let allDataCells = document.querySelectorAll('#spreadsheet td');
    allDataCells.forEach(cell => {
        if (parseInt(cell.dataset.colIndex) === colIndex) {
            columnCells.push(cell);
        }
    });

    // Eliminar celdas de datos
    columnCells.forEach(cell => cell.remove());

    // Eliminar el encabezado de columna
    target.remove();

    console.log(`Columna ${columnName} procesada: Contenido borrado=${contentCleared}, Color aplicado=${backgroundColored}, Columna eliminada.`);
}
