// --- Initialization Functions ---

function setupCellEditing() {
    document.querySelectorAll('[contenteditable="true"]').forEach(cell => {
        // Add focus listener to handle selection and potential key events
        cell.addEventListener('focus', function () {
            // When focusing on a cell, ensure the row label is updated if necessary (though not strictly needed for this fix)
            const row = this.closest('tr');
            if (row && !selectedRow) {
                selectRow(row);
            }
        });

        // Add keydown listener to handle content manipulation (like deleting the whole row/clearing content)
        cell.addEventListener('keydown', function (e) {
            // If Delete or Backspace is pressed, and we are in a cell that belongs to a selected row, 
            // we rely on the global document keydown listener for the bulk clear action.
            // However, if the user just wants to delete content *within* the cell, standard browser behavior handles it.
        });
    });

    // Add click listeners to row labels (the number column)
    document.querySelectorAll('.row-label').forEach(label => {
        label.addEventListener('click', function () {
            const row = this.closest('tr');
            selectRow(row);
        });
    });
}

function selectRow(rowElement) {
    // Deselect all rows first
    document.querySelectorAll('.row-label').forEach(label => {
        label.removeAttribute('data-selected');
        label.style.backgroundColor = ''; // Reset background color
    });

    // Select the clicked row
    if (rowElement) {
        selectedRow = rowElement;
        const label = rowElement.querySelector('.row-label');
        if (label) {
            label.setAttribute('data-selected', 'true');
            // Highlight the selected row's label background
            label.style.backgroundColor = '#e0f7fa'; 
        }
    } else {
        selectedRow = null;
    }
}

