 * @param {HTMLElement} cellElement - The TD element.
 * @returns {string} The text content of the cell.
 */
function getValueFromCell(cellElement) {
    // Use innerText to get clean visible text content
    return cellElement ? cellElement.innerText.trim() : '';
}

/**
 * Calculates a formula string (e.g., "=A1+B1") and evaluates it.
 * @param {HTMLElement} targetElement - The TD element where the result should be displayed.
 */
function calculateFormula(targetElement) {
    const row = targetElement.closest('tr');
    if (!row) return;

    // Assuming simple addition for demonstration purposes based on typical spreadsheet needs
    let formulaString = '';
    let values = [];

    // Iterate over all data cells in the same row (excluding the label column)
    const cellsInRow = Array.from(row.querySelectorAll('td')); 

    cellsInRow.forEach((cell, index) => {
        if (index > 0) { // Skip the first cell which is the row label
            // Get the data-cell attribute to construct the reference (e.g., A3, B3)
            const cellRef = cell.getAttribute('data-cell');
            if (cellRef) {
                values.push(getValueFromCell(cell));
                formulaString += `${cellRef}`;
                if (index < cellsInRow.length - 1) {
                    formulaString += '+';
                }
            }
        }
    });

    // Simple calculation: sum of all values found in the row
    let total = 0;
    values.forEach(val => {
        const numVal = parseFloat(val);
        if (!isNaN(numVal)) {
            total += numVal;
        }
    });

    // Display the result, formatted as a formula if needed, or just the number
    targetElement.innerText = total !== 0 ? total : '';
}


