/**
 * Retrieves the value from a cell reference (e.g., "B1").
 * @param {string} cellRef - The A1 notation string.
 * @returns {string|null} The content of the cell or null if invalid/empty.
 */
function getValueFromCell(cellRef) {
    if (!cellRef || typeof cellRef !== 'string') return null;

    // Regex to match column letters (A-Z) and row numbers (1-99+)
    const match = cellRef.match(/([A-Z]+)(\d+)/i);
    if (!match) return null;

    const colLetters = match[1].toUpperCase();
    const rowNumber = parseInt(match[2]);

    // Convert column letters to index (A=0, B=1, ...)
    let colIndex = 0;
    for (let i = 0; i < colLetters.length; i++) {
        colIndex += (colLetters.charCodeAt(i) - 'A'.charCodeAt(i));
    }

    // Get the row element by ID (e.g., #row-1)
    const rowElement = document.getElementById(`row-${rowNumber}`);
    if (!rowElement) return null;

    // Data cells start from index 0 in the row's children, but we skip the label cell (index 0)
    // The actual data column index is colIndex. Since the first child is the label (<th>),
    // the target TD element will be at index `colIndex + 1`.
    const cells = Array.from(rowElement.querySelectorAll('td'));

    if (cells[colIndex]) {
        return cells[colIndex].textContent.trim();
    }
    return null;
}


