        // 1. Extract cell references from the formula string
        const cellReferences = [...formula.matchAll(/[A-Z]+\d+/gi)];

        if (cellReferences.length === 0) {
            targetElement.textContent = "Error: No valid cells found.";
            return;
        }

        // 2. Get the current values of these referenced cells
        const values = cellReferences.map(ref => getValueFromCell(ref));

        // 3. Evaluate the formula using the retrieved values
        let evaluatedFormula = formula;
        values.forEach((value, index) => {
            // Replace cell references in the string with their actual numeric/string value
            evaluatedFormula = evaluatedFormula.replace(new RegExp(cellReferences[index][0], 'g'), 
                                                        typeof value === 'number' ? value : `'${String(value).replace(/'/g, "\\'")}'`);
        });

        // Use Function constructor for safe evaluation (safer than eval())
        const result = new Function(`return ${evaluatedFormula}`)();

        // 4. Update the cell content and trigger UI updates
        targetElement.textContent = result;
        updateCellStyles(targetElement, result);

    } catch (e) {
        console.error("Error calculating formula:", e);
        targetElement.textContent = "ERROR";
    }
}


/**
 * Iterates through all cells and recalculates formulas for the entire sheet.
 */
function calculateAllFormulas() {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // Select all data cells (<td>) in the body
    const dataCells = spreadsheet.querySelectorAll('tbody td');

    dataCells.forEach(cell => {
        // Check if the cell content looks like a formula
        const text = cell.textContent.trim();
        if (text && text.startsWith('=')) {
            calculateFormula(cell);
        }
    });
}


/**
 * Updates background color and potentially other styles based on the calculated result.
 * @param {HTMLElement} targetElement - The <td> element that was updated.
 * @param {*} value - The resulting value of the cell.
 */
function updateCellStyles(targetElement, value) {
    // Reset existing styles first
    targetElement.style.backgroundColor = '';

    if (typeof value === 'number' && !isNaN(value)) {
        // Example: Highlight positive numbers green and negative numbers red
        if (value > 0) {
            targetElement.style.backgroundColor = '#d4edda'; // Light Green
        } else if (value < 0) {
            targetElement.style.backgroundColor = '#f8d7da'; // Light Red
        }
    } else if (typeof value === 'string' && value.toLowerCase().includes('error')) {
         // Highlight error messages
        targetElement.style.backgroundColor = '#ffcccc'; 
    }
}

/**
