function deleteColumn(colLetter) {
    const spreadsheet = document.getElementById('spreadsheet');
    if (!spreadsheet) return;

    // 1. Remove the column header letter
    const headerCells = spreadsheet.querySelector('thead th[data-col]');
    let targetHeader = null;
    for (let i = 0; i < headerCells.length; i++) {
        if (headerCells[i].innerText.toUpperCase() === colLetter) {
            targetHeader = headerCells[i];
            break;
        }
    }

    if (!targetHeader) {
        console.warn(`Column ${colLetter} header not found.`);
        return false;
    }

    // Remove the specific TH element from thead
    targetHeader.remove();


    // 2. Iterate through all body rows and remove the corresponding TD cell
    const rows = spreadsheet.querySelectorAll('tbody tr');
    let columnRemovedCount = 0;

    rows.forEach(row => {
        // Find the specific TD element in this row that matches the column letter
        const cellsInRow = row.querySelectorAll('td[data-cell]');
        for (const cell of cellsInRow) {
            if (cell.getAttribute('data-col') === colLetter) {
                cell.remove();
                columnRemovedCount++;
                break; // Only one TD per column per row
            }
        }
    });

    console.log(`Column ${colLetter} deleted successfully.`);
    return true;
}
