function deleteColumn(columnLetter) {
    const column = columnLetter.toUpperCase();
    if (!/[A-Z]/.test(column)) return;

    const tbody = document.querySelector('#spreadsheet tbody');
    if (!tbody) return;

    // Calculate the index of the column (A=0, B=1, ...) relative to data columns A-J
    const charCodeA = 'A'.charCodeAt(0);
    let columnIndexToDelete = column.charCodeAt(0) - charCodeA;

    if (columnIndexToDelete < 0 || columnIndexToDelete > 9) { // J is index 9
        console.error("Column letter out of range.");
        return;
    }

    // 1. Remove cells from all rows in the body
    const rows = tbody.querySelectorAll('tr');
    rows.forEach(row => {
        // We are looking for the Nth TD element (where N is columnIndexToDelete)
        const cells = row.querySelectorAll('td');
        if (cells[columnIndexToDelete]) {
            cells[columnIndexToDelete].remove();
        }
    });

    // 2. Remove header from thead
    const headerRow = document.querySelector('#spreadsheet thead tr');
    // The structure is: [Empty TH] [A TH] [B TH] ...
    // A is at index 1, B is at index 2, etc.
    const allHeaders = headerRow.querySelectorAll('th');
    const headerIndexToRemove = columnIndexToDelete + 1; // Offset by the empty corner cell

    if (allHeaders[headerIndexToRemove]) {
        allHeaders[headerIndexToRemove].remove();
    } else {
        console.error("Could not find corresponding header element.");
    }
}
