```javascript
function toggleColumn(letter) {
    const headerRow = document.querySelector('#spreadsheet thead tr');
    const columnHeaders = Array.from(headerRow.children).slice(1); // Excluir la primera celda vacía

    // 1. Ocultar/Mostrar el encabezado de columna (A, B, C...)
    const headerCell = Array.from(columnHeaders).find(th => th.textContent.trim() === letter);
    if (!headerCell) return;

    let isHidden = headerCell.style.display === 'none';

    if (isHidden) {
        // Mostrar columna: restaurar visibilidad en todos los elementos de la columna
        headerCell.style.display = ''; // Restaura el display original
        document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(cell => {
            cell.style.display = '';
        });

        // Actualizar botones: Ocultar -> Mostrar
        const controlDiv = document.querySelector('.column-control');
        if (controlDiv) {
            document.getElementById(`toggle-${letter}`).style.display = 'none';
            document.getElementById(`show-${letter}`).style.display = '';
        }

    } else {
        // Ocultar columna: aplicar display: none en todos los elementos de la columna
        headerCell.style.display = 'none';
        document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(cell => {
            cell.style.display = 'none';
        });

        // Actualizar botones: Mostrar -> Ocultar
        const controlDiv = document.querySelector('.column-control');
        if (controlDiv) {
            document.getElementById(`toggle-${letter}`).style.display = '';
            document.getElementById(`show-${letter}`).style.display = 'inline';
        }
    }

    // Forzar la actualización de cálculos después de ocultar/mostrar columnas
    calculateAllFormulas();
}
